import os, re

# Load all grids from session
d = os.environ.get('RLM_SESSION_DIR', '')
if d:
    sessions_path = os.path.join(d, '../../sessions')
    if os.path.exists(sessions_path):
        jsonl_path = os.path.join(sessions_path, os.path.basename(d) + '.jsonl')
        if os.path.exists(jsonl_path):
            content = open(jsonl_path).read().replace('\\n', '\n')

            G = {}
            # Parse demo pairs
            for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
                k, h, w = m[1], int(m[2]), int(m[3])
                rows = [r.split() for r in content[m.end():].split('\n')[:h]]
                if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
                    G[k] = [[int(x) for x in r] for r in rows]
            print("Loaded grids:", sorted(G.keys()))
else:
    print("No RLM_SESSION_DIR found")

