# Check: for each non-2 cell, does dist_to_nearest_2 <= 1 explain why it became 1?

def dist_to_nearest_2(grid, r, c):
    h, w = len(grid), len(grid[0])
    min_dist = float('inf')
    for tr in range(h):
        for tc in range(w):
            if grid[tr][tc] == 2:
                d = abs(tr - r) + abs(tc - c)
                min_dist = min(min_dist, d)
    return min_dist

# Count neighbors that are 2
def count_2_neighbors(grid, r, c):
    h, w = len(grid), len(grid[0])
    neighbors = [(r+dr, c+d) for dr in [-1, 0, 1] for d in [-1, 0, 1]]
    count = 0
    for nr, nc in neighbors:
        if 0 <= nr < h and 0 <= nc < w:
            if grid[nr][nc] == 2:
                count += 1
    return count

