def get_3_connected_component(grid, start_r, start_c):
    """Find all 3s connected to start (ignoring 0s, 2s as barriers)"""
    h, w = len(grid), len(grid[0])
    visited = set()
    stack = [(start_r, start_c)]

    while stack:
        r, c = stack.pop()
        key = (r, c)
        if key in visited:
            continue
        visited.add(key)

        if grid[r][c] != 3:
            continue

        for dr, dc in [-1, 0, 1]:
            for dc_other in [-1, 0, 1]:
                nr, nc = r + dr, c + dc_other
                if 0 <= nr < h and 0 <= nc < w:
                    if (nr, nc) not in visited and grid[nr][nc] == 3:
                        stack.append((nr, nc))
    return visited

