def count_influential_twos(grid, r, c, max_dist=3):
    """Count how many 2s can 'reach' this cell within max_dist"""
    h, w = len(grid), len(grid[0])

    influential = []
    for tr, tc in [(tr, tc) for tr in range(h) for tc in range(w) if grid[tr][tc] == 2]:
        d = abs(r - tr) + abs(c - tc)
        if d <= max_dist:
            # Check if there's a clear path (only 3s and possibly 0s)
            has_path = True
            visited = set()
            queue = [(tr, tc)]

            while queue:
                cr, cc = queue.pop(0)
                if (cr, cc) in visited:
                    continue
                visited.add((cr, cc))

                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if (nr, nc) in visited or not (0 <= nr < h and 0 <= nc < w):
                        continue

                    v = grid[nr][nc]
                    if v == 3:
                        visited.add((nr, nc))
                        queue.append((nr, nc))
                    elif v == 0:
                        visited.add((nr, nc))
                        queue.append((nr, nc))

                    if (nr, nc) == (r, c):
                        has_path = True
                        break

                if has_path:
                    break

            if has_path:
                influential.append((tr, tc, d))

    return influential

