def solve_reach_nonzero(grid):
    h, w = len(grid), len(grid[0])
    result = []

    for r in range(h):
        new_row = list(grid[r])
        for c in range(w):
            if grid[r][c] == 3:
                # Check if we can reach a 2 from this position in <= 2 steps via non-zeros
                visited = [[False]*w for _ in range(h)]

                # BFS starting from this 3
                queue = [(r,c,0)]
                found = False

                while queue and not found:
                    cr, cc, dist = queue.pop(0)

                    if dist >= 2:
                        continue

                    # Can move to adjacent non-zero cells
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if not visited[nr][nc] and grid[nr][nc] != 0:
                                if visited[nr][nc] or grid[nr][nc] != 3:  # Already checked or not a 3
                                    pass
                                else:
                                    visited[nr][nc] = True
                                    queue.append((nr, nc, dist+1))

                # Now do reverse - can we reach a 2 from here?
                visited2 = [[False]*w for _ in range(h)]
                queue = [(r,c,0)]

                while queue:
                    curr_r, curr_c, d = queue.pop(0)
                    if d > 2:
                        continue

                    # Check if current cell is a 2
                    if grid[curr_r][curr_c] == 2:
                        found = True
                        break

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = curr_r+dr, curr_c+dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if not visited2[nr][nc] and grid[nr][nc] != 0 and grid[nr][nc] != 3:
                                continue
                            if not visited2[nr][nc]:
                                visited2[nr][nc] = True
                                queue.append((nr, nc, d+1))

                if found and grid[r][c] == 3:
                    new_row[c] = 1

        result.append(new_row)

    return result

