print("=== Reachable 2-count based ===")

def solve_reachable_2count(grid):
    from collections import deque

    h, w = len(grid), len(grid[0])
    result = []

    for r in range(h):
        new_row = list(grid[r])

        for c in range(w):
            if grid[r][c] == 3:
                # Find all reachable 2s via paths through non-zero cells
                visited = [[False]*w for _ in range(h)]
                queue = deque([(r,c)])
                found_twos = set()

                while queue:
                    curr_r, curr_c = queue.popleft()

                    if grid[curr_r][curr_c] == 2:
                        found_twos.add((curr_r, curr_c))

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = curr_r+dr, curr_c+dc
                        if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc]:
                            visited[nr][nc] = True
                            if grid[nr][nc] != 0:
                                queue.append((nr, nc))

                # If we can reach >= 2 distinct 2s, convert this 3
                if len(found_twos) >= 2:
                    new_row[c] = 1

        result.append(new_row)

    return result

